from collections import deque

def bfs_shortest_distance(graph, source, target):
    if source == target:
        return 0
    queue = deque([(source, 0)])
    visited = {source}
    while queue:
        node, dist = queue.popleft()
        for neighbor in graph.get(node, []):
            if neighbor == target:
                return dist + 1
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, dist + 1))
    return -1

def in_degree_nodes(graph):
    in_degree = {node: 0 for node in graph}
    for node in graph:
        for neighbor in graph[node]:
            in_degree[neighbor] = in_degree.get(neighbor, 0) + 1
    return [node for node, deg in in_degree.items() if deg == 0]

def is_fully_reachable(graph, dispatch):
    visited = set()
    queue = deque([dispatch])
    visited.add(dispatch)
    while queue:
        node = queue.popleft()
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
    return len(visited) == len(graph)

def campus_navigation(graph, source, dispatch):
    dist = bfs_shortest_distance(graph, source, 'E')
    hubs = in_degree_nodes(graph)
    reachable = is_fully_reachable(graph, dispatch)
    return {
        'shortest_distance_to_E': dist,
        'no_dependency_hubs': hubs,
        'all_buildings_reachable': reachable
    }

