from collections import defaultdict, deque

def is_valid_bst_and_acyclic_dag(edges):
    if not edges:
        return True, []
    graph = defaultdict(list)
    parent = {}
    in_degree = {}
    nodes = set()
    for u, v in edges:
        graph[u].append(v)
        parent[v] = u
        nodes.add(u)
        nodes.add(v)
        in_degree[v] = in_degree.get(v, 0) + 1
        in_degree[u] = in_degree.get(u, 0)
    root = None
    for node in nodes:
        if node not in in_degree:
            root = node
            break
    if root is None:
        return False, list(nodes)
    for u, v in edges:
        if v in parent and parent[v] != u:
            return False, [u, v]
    # BST validation via traversal
    def validate_bst(node, low, high):
        if node is None:
            return True
        val = node
        if not (low < val < high):
            return False
        left = graph.get(node, [])
        right = [n for n in graph.get(node, []) if n not in left]  # heuristic split
        # Better: require left < node < right via explicit left/right sets
        # For this challenge, assume edges encode left/right by parity or naming
        # We use a stricter approach: require all children < node for left, > node for right
        # Simplified: check no child violates BST if we assume left/right from structure
        # Full solution requires left/right markers; here we validate acyclic + BST-like ordering
        return validate_bst(left[0] if left else None, low, val) and validate_bst(right[0] if right else None, val, high)
    # Cycle detection via DFS
    visited = set()
    rec_stack = set()
    cycle = []
    def dfs_cycle(u, path):
        visited.add(u)
        rec_stack.add(u)
        path.append(u)
        for v in graph.get(u, []):
            if v not in visited:
                if dfs_cycle(v, path):
                    return True
            elif v in rec_stack:
                idx = path.index(v)
                cycle.extend(path[idx:] + [v])
                return True
        rec_stack.remove(u)
        path.pop()
        return False
    if dfs_cycle(root, []):
        return False, cycle
    # DAG check via topological sort
    queue = deque([n for n in nodes if in_degree.get(n, 0) == 0])
    topo = []
    while queue:
        u = queue.popleft()
        topo.append(u)
        for v in graph.get(u, []):
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)
    if len(topo) != len(nodes):
        return False, list(nodes)
    # BST ordering check: all left descendants < node < right descendants
    # We assume edges to smaller values are left, larger are right
    def check_bst_order(u, low, high):
        if u is None:
            return True
        if not (low < u < high):
            return False
        for v in graph.get(u, []):
            if v < u:
                if not check_bst_order(v, low, u):
                    return False
            else:
                if not check_bst_order(v, u, high):
                    return False
        return True
    if not check_bst_order(root, float('-inf'), float('inf')):
        return False, ['BST_violation']
    return True, []

edges = [
    ('5', '3'),
    ('5', '7'),
    ('3', '2'),
    ('3', '4'),
    ('7', '6'),
    ('7', '8')
]
print(is_valid_bst_and_acyclic_dag(edges))
